snippets.css:
/* KM Code Pro — Ambient Specular Glow & Glass Depth */
[data-t3-app] [data-t3-surface="composer-body"],
[data-t3-app] [data-chat-composer-surface="true"] {
  box-shadow:
    0 12px 36px -10px rgb(0 0 0 / 55%),
    0 0 0 1px color-mix(in srgb, var(--ring) 20%, transparent),
    0 0 24px -4px color-mix(in srgb, var(--ring) 14%, transparent) !important;
  transition: box-shadow 240ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

[data-t3-app] [data-t3-surface="composer"]:focus-within [data-t3-surface="composer-body"],
[data-t3-app] [data-t3-surface="composer"]:focus-within [data-chat-composer-surface="true"] {
  box-shadow:
    0 16px 44px -8px rgb(0 0 0 / 65%),
    0 0 0 1.5px color-mix(in srgb, var(--ring) 55%, white 15%),
    0 0 32px -2px color-mix(in srgb, var(--ring) 28%, transparent) !important;
}

[data-t3-app] [data-t3-surface="sidebar"] [data-active="true"],
[data-t3-app] [data-app-sidebar] [data-active="true"] {
  border-radius: 8px !important;
  box-shadow:
    inset 0 1px 0 0 rgb(255 255 255 / 10%),
    0 1px 3px 0 rgb(0 0 0 / 30%) !important;
  transition: all 150ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

[data-t3-app] [role="dialog"],
[data-t3-app] [data-t3-surface="command-palette"],
[data-t3-app] [role="menu"] {
  border-radius: 12px !important;
  box-shadow:
    0 24px 64px -16px rgb(0 0 0 / 75%),
    0 0 0 1px color-mix(in srgb, var(--contrast-border) 80%, transparent),
    inset 0 1px 0 0 rgb(255 255 255 / 10%) !important;
}

/* KM Code Pro — Editorial Monoline Code & Markdown */
[data-t3-app] [data-t3-surface="code-block"],
.chat-markdown .chat-markdown-codeblock {
  border-radius: 9px !important;
  border: 1px solid color-mix(in srgb, var(--contrast-border) 70%, transparent) !important;
  box-shadow: 0 4px 16px -4px rgb(0 0 0 / 30%) !important;
  overflow: hidden !important;
}

.chat-markdown .chat-markdown-codeblock-header {
  border-bottom: 1px solid color-mix(in srgb, var(--contrast-border) 50%, transparent) !important;
  font-family: var(--font-mono) !important;
  font-size: 0.72rem !important;
  letter-spacing: 0.05em !important;
  text-transform: uppercase !important;
  padding: 0.35rem 0.75rem !important;
}

.chat-markdown :not(pre) > code {
  font-family: var(--font-mono) !important;
  font-size: 0.84em !important;
  font-weight: 450 !important;
  padding: 0.15rem 0.4rem !important;
  border-radius: 5px !important;
  border: 1px solid color-mix(in srgb, var(--contrast-border) 60%, transparent) !important;
  background: color-mix(in srgb, var(--muted) 70%, transparent) !important;
  letter-spacing: -0.01em !important;
}

.chat-markdown blockquote {
  border-left: 3px solid var(--primary) !important;
  background: color-mix(in srgb, var(--primary) 4%, transparent) !important;
  border-radius: 0 8px 8px 0 !important;
  padding: 0.6rem 1rem !important;
  margin: 0.75rem 0 !important;
  font-style: normal !important;
}

/* KM Code Pro — Cyber Neon Send Button & Stealth Scrollbars */
[data-t3-app] [data-t3-surface="composer"] [data-t3-part="send-button"],
[data-t3-app] [data-chat-composer-surface="true"] [data-t3-part="send-button"] {
  background-image: linear-gradient(135deg, #00d2ff 0%, #3264ff 50%, #ff00b4 100%) !important;
  color: #ffffff !important;
  border: none !important;
  font-weight: 550 !important;
  box-shadow: 0 2px 14px -2px rgb(0 210 255 / 45%) !important;
  transition: all 180ms ease !important;
}

[data-t3-app] [data-t3-surface="composer"] [data-t3-part="send-button"]:hover,
[data-t3-app] [data-chat-composer-surface="true"] [data-t3-part="send-button"]:hover {
  filter: brightness(1.12) !important;
  box-shadow:
    0 4px 20px -1px rgb(255 0 180 / 50%),
    0 0 14px rgb(0 210 255 / 35%) !important;
  transform: translateY(-0.5px) !important;
}

::-webkit-scrollbar {
  width: 5px !important;
  height: 5px !important;
}

::-webkit-scrollbar-track {
  background: transparent !important;
}

::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--contrast-border) 60%, transparent) !important;
  border-radius: 999px !important;
  transition: background 150ms ease !important;
}

::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--ring) 75%, white 25%) !important;
  box-shadow: 0 0 8px color-mix(in srgb, var(--ring) 50%, transparent) !important;
}

/* KM Code Pro — Compact Zen Chrome & Clean Borders */
[data-t3-app] [data-t3-surface="sidebar"] nav {
  gap: 2px !important;
}

[data-t3-app] [data-t3-surface="sidebar"] button {
  min-height: 28px !important;
  font-size: 0.8125rem !important;
}

[data-t3-app] [data-t3-surface="title-area"] {
  border-bottom: 1px solid color-mix(in srgb, var(--contrast-border) 40%, transparent) !important;
}
